# Datafiles this bake REFUSED.  `write_module` skips any
# record still carrying a cell from one of these, because
# records keep what earlier bakes wrote and nothing else
# removes it -- Schoen p.14 went on shipping for exactly
# that reason after Evolver's area disqualified it.
FE_HELD = [
 "CScell.fe",
 "CYcell.fe",
 "I-8.fe",
 "I-9.fe",
 "N14.fe",
 "N26.fe",
 "N38.fe",
 "Scell.fe",
 "disphenoid35adj.fe",
 "disphenoid43adj.fe",
 "disphenoid51adj.fe",
 "disphenoid55adj.fe",
 "mantaadj.fe",
 "s14adj.fe",
 "ycell.fe"
]

# The table is keyed by GENERATOR ROW; records are looked
# up by the slug each row's record carries, which for the
# surfaces the database already knew is its existing slug.
_BY_SLUG = {c.get('record_slug', k): c
            for k, c in FE_CELLS.items()}


def facts_for(slug):
    """`definition` fragment for a slug, or {}."""
    cell = _BY_SLUG.get(slug)
    if not cell:
        return {}
    return {'definition': {'evolver_cell': cell}}
